import {
	listProjectBranchLogFields,
	listProjectBranchLogFieldValues,
	queryProjectBranchLogs,
} from "../../client/sdk.gen.js";
import type {
	ListProjectBranchLogFieldValuesData,
	ProjectBranchLogFieldValuesResponse,
	ProjectBranchLogRecord,
	ProjectBranchLogsQueryRequest,
	ProjectBranchLogsQueryResponse,
} from "../../client/types.gen.js";
import type { CallOptions, RequestContext } from "../context.js";
import { NeonClientError } from "../errors.js";
import { type Paginated, paginate } from "../paginate.js";
import {
	invalidParamsResult,
	validateCallOptions,
	validateParams,
} from "../params.js";
import type { NeonResult, Outcome } from "../result.js";

/**
 * Filters for {@link Logs.query}.
 *
 * `cursor` is absent because {@link Paginated} owns paging: the endpoint requires
 * every filter and the time window to be repeated unchanged on each page, and
 * threading the cursor here is what guarantees that.
 */
export type LogQueryInput = Omit<ProjectBranchLogsQueryRequest, "cursor">;

/** Query parameters for {@link Logs.fieldValues}. */
export type LogFieldValuesQuery = NonNullable<
	ListProjectBranchLogFieldValuesData["query"]
>;

export type LogsQueryParams = {
	projectId: string;
	branchId: string;
} & LogQueryInput;
export type LogsFieldsParams = { projectId: string; branchId: string };
export type LogsFieldValuesParams = {
	projectId: string;
	branchId: string;
	fieldName: string;
} & LogFieldValuesQuery;

/**
 * Branch-scoped logs emitted by the services running on a branch — Neon Functions,
 * object storage, and Postgres computes. Grouped under `neon.logs.*` alongside the
 * other branch-scoped product surfaces.
 *
 * Private Beta. Telemetry is region-gated, so a branch outside an enabled region answers
 * `404` with `reason: "telemetry_not_enabled"` rather than an empty result — treat that
 * as an ordinary outcome. A branch that has telemetry but nothing recorded answers `200`
 * with an empty array, and one whose backend is down answers `503`, which the client
 * retries on by default.
 *
 * The spec is wider than the backend: of the three `source` values only `function` and
 * `storage` were observed emitting, and `minimum_severity` can be rejected as unsupported
 * by a branch's log backend, where `severity_text` still works.
 */
export class Logs<DThrow extends boolean> {
	readonly #ctx: RequestContext;

	constructor(ctx: RequestContext) {
		this.#ctx = ctx;
	}

	/**
	 * Query branch logs (cursor-paginated). Every supplied filter is combined with
	 * `AND`.
	 *
	 * Give the window as either `since` or `start_time` — supplying both is rejected.
	 * `logql` replaces the seven content filters rather than adding to them, while
	 * `limit`, `sort_order`, and the time window still apply alongside it. With no
	 * window the query covers the last hour, and seven days is the widest range served.
	 *
	 * @apiCall POST /projects/{project_id}/branches/{branch_id}/logs/query (cursor-paginated)
	 */
	query(params: LogsQueryParams): Paginated<ProjectBranchLogRecord, DThrow>;
	query<Throw extends boolean = DThrow>(
		params: LogsQueryParams,
		opts: CallOptions<Throw>,
	): Paginated<ProjectBranchLogRecord, Throw>;
	query(
		params: LogsQueryParams,
		opts?: CallOptions,
	): Paginated<ProjectBranchLogRecord, boolean> {
		const invalid =
			validateParams(params, "logs.query", {
				projectId: "string",
				branchId: "string",
			}) ?? validateCallOptions(opts);
		const { projectId, branchId, ...input } = invalid
			? ({} as LogsQueryParams)
			: params;
		// Snapshot the filters. The endpoint returns wrong results unless every page
		// repeats them unchanged, and a `Paginated` is lazy — reading `input` per page
		// would let a caller mutating it afterwards change the query mid-walk.
		const filters = { ...input };
		return paginate<ProjectBranchLogRecord, ProjectBranchLogsQueryResponse>(
			async (cursor, signal) => {
				if (invalid) throw invalid;
				const page = await queryProjectBranchLogs({
					client: this.#ctx.client,
					path: { project_id: projectId, branch_id: branchId },
					body: { ...filters, cursor },
					throwOnError: false,
					signal,
				});
				// Truncated with nothing to resume from: the remaining records are
				// unreachable. Stopping here would hand back a partial page that looks
				// like the whole result.
				if (page.data?.is_truncated && !page.data.next_cursor) {
					return {
						response: page.response,
						error: new NeonClientError(
							"Neon reported more log records than it returned but gave no cursor to reach them.",
						),
					};
				}
				return page;
			},
			(data) => ({
				items: data?.logs ?? [],
				// `next_cursor` is present but empty on the last page, so truncation is
				// the flag that ends the walk.
				cursor: data?.is_truncated ? data.next_cursor : undefined,
			}),
			() => this.#ctx.deadlineFor(opts),
			this.#ctx.shouldThrow(opts),
		);
	}

	/**
	 * List the log fields whose values {@link Logs.fieldValues} can enumerate on
	 * this branch. Computed per branch and grows as fields are observed, so read it
	 * rather than assuming a fixed set.
	 *
	 * @apiCall GET /projects/{project_id}/branches/{branch_id}/logs/fields
	 */
	fields(params: LogsFieldsParams): Promise<Outcome<string[], DThrow>>;
	fields<Throw extends boolean = DThrow>(
		params: LogsFieldsParams,
		opts: CallOptions<Throw>,
	): Promise<Outcome<string[], Throw>>;
	fields(
		params: LogsFieldsParams,
		opts?: CallOptions,
	): Promise<string[] | NeonResult<string[]>> {
		const invalid = validateParams(params, "logs.fields", {
			projectId: "string",
			branchId: "string",
		});
		if (invalid) {
			return invalidParamsResult<string[]>(
				invalid,
				this.#ctx.shouldThrow(opts),
			);
		}
		const { projectId, branchId } = params;
		return this.#ctx.run(
			opts,
			(client, signal) =>
				listProjectBranchLogFields({
					client,
					path: { project_id: projectId, branch_id: branchId },
					throwOnError: false,
					signal,
				}),
			(data) => data.fields,
		);
	}

	/**
	 * List the distinct values observed for one log field, for use as a filter.
	 * `fieldName` must be one of the names {@link Logs.fields} reports; anything else is
	 * rejected with `unknown_field`. The enumerable set and the set {@link Logs.query} can
	 * filter on overlap rather than nest: `source` is a filter but is not enumerable, and
	 * `entity_type` is enumerable but is not a filter.
	 *
	 * The whole response is returned rather than the bare values because
	 * `is_truncated` decides whether the list can be trusted: when it is `true` the
	 * values are an arbitrary subset, and the window or `source` needs narrowing
	 * before filtering on them.
	 *
	 * @apiCall GET /projects/{project_id}/branches/{branch_id}/logs/fields/{field_name}/values
	 */
	fieldValues(
		params: LogsFieldValuesParams,
	): Promise<Outcome<ProjectBranchLogFieldValuesResponse, DThrow>>;
	fieldValues<Throw extends boolean = DThrow>(
		params: LogsFieldValuesParams,
		opts: CallOptions<Throw>,
	): Promise<Outcome<ProjectBranchLogFieldValuesResponse, Throw>>;
	fieldValues(
		params: LogsFieldValuesParams,
		opts?: CallOptions,
	): Promise<
		| ProjectBranchLogFieldValuesResponse
		| NeonResult<ProjectBranchLogFieldValuesResponse>
	> {
		const invalid = validateParams(params, "logs.fieldValues", {
			projectId: "string",
			branchId: "string",
			fieldName: "string",
		});
		if (invalid) {
			return invalidParamsResult<ProjectBranchLogFieldValuesResponse>(
				invalid,
				this.#ctx.shouldThrow(opts),
			);
		}
		const { projectId, branchId, fieldName, ...query } = params;
		return this.#ctx.run(
			opts,
			(client, signal) =>
				listProjectBranchLogFieldValues({
					client,
					path: {
						project_id: projectId,
						branch_id: branchId,
						field_name: fieldName,
					},
					query,
					throwOnError: false,
					signal,
				}),
			(data) => data,
		);
	}
}
